%%\ 1. Entorno y Comandos Básicos
clc;        % Limpia la Command Window (análogo a clear en terminal)
clear;      % Borra todas las variables del Workspace
% save('mis_datos.mat'); % Guarda el entorno de trabajo actual
% load('mis_datos.mat'); % Carga las variables guardadas
a = "hello";
disp('hola como estas') %[output:318a168d]
%%
%%\ 2. Vectores y Matrices (Equivalente a NumPy)
% Creación manual
A = [1, 2, 3; 4, 5, 6]; % Matriz 2x3 (filas separadas por ;)
disp(A) %[output:008c7ba5]
% Secuencias y espaciado
v = 0:2:10;             % Vector [0, 2, 4, 6, 8, 10] (inicio:paso:fin)
x = linspace(0, 1, 5);  % 5 valores equiespaciados entre 0 y 1

% Arreglos comunes
Z = zeros(2, 3);        % Matriz de ceros 2x3
U = ones(3, 3);         % Matriz de unos 3x3
R = rand(1, 5);         % Vector de 5 números aleatorios (uniforme 0-1)
%%
%%\ 3. Indexación y Modificación (OJO: MATLAB usa base 1, no 0)
elemento = A(2, 3);     % Fila 2, columna 3 (valor 6)
fila = A(1, :);         % Extrae toda la fila 1
columna = A(:, end);    % Extrae la última columna ('end' = último índice)

A(1, 1) = 99;           % Modifica un elemento

%%\ 4. Cálculos con Arreglos
v1 = [1, 2, 3];
v2 = [4, 5, 6];

% Operaciones elemento a elemento (requieren el punto '.' antes del operador)
prod_elem = v1 .* v2;   % Multiplicación tipo Hadamard: [4, 10, 18]
pot_elem = v1 .^ 2;     % Cuadrado de cada elemento: [1, 4, 9]

% Multiplicación matricial (álgebra lineal estándar)
mat_mult = A * [1; 2; 3]; % (2x3) * (3x1) = (2x1)
%%
%%\ 5. Llamadas a Funciones (Múltiples argumentos de salida)
arr = [10, 45, 2, 88, 14];
[valor_max, indice_max] = max(arr); % Devuelve el máximo (88) y su posición (4)

%%\ 6. Visualización de Datos (Similar a matplotlib.pyplot)
t = linspace(0, 2*pi, 100);
y1 = sin(t);
y2 = cos(t);

figure;                 % Abre una nueva ventana de figura %[output:827da149]
plot(t, y1, 'r-', 'LineWidth', 2); % Línea roja continua %[output:827da149]
hold on;                % Mantiene el gráfico actual para añadir más capas %[output:827da149]
plot(t, y2, 'b--');     % Línea azul discontinua %[output:827da149]
hold off;               % Libera el gráfico %[output:827da149]

title('Ondas Trigonométricas'); %[output:827da149]
xlabel('Tiempo (t)'); %[output:827da149]
ylabel('Amplitud'); %[output:827da149]
legend('Seno', 'Coseno'); %[output:827da149]
grid on; %[output:827da149]
%%\ 7. Importación de Datos (Variables Table ~ Pandas DataFrame)
% Simulamos una tabla internamente (en la práctica se usa readtable)
% T = readtable('datos.csv');
Nombres = ["Ana"; "Luis"; "Marta"];
Edades = [25; 30; 28];
T = table(Nombres, Edades);

% Acceso a columnas (retorna array/celda)
array_edades = T.Edades; 
%%
%%\ 8. Arreglos Lógicos (Máscaras booleanas)
datos = [15, -4, 22, -9, 30];
mascara = datos > 0;             % Arreglo lógico: [1, 0, 1, 0, 1]
datos_positivos = datos(mascara);% Filtrado rápido: [15, 22, 30]

% Combinación lógica (& para AND, | para OR)
en_rango = datos(datos > 10 & datos < 25); 
%%
%%\ 9. Programación (Control de Flujo)
% Condicionales
clc
val = input('introduce a value: ');
if val > 15 %[output:group:58c50780]
    disp('Mayor que 15');
elseif val == 10
    disp('Es exactamente 10');
else
    disp('Menor que 10'); %[output:3ea1e50e]
end  %[output:group:58c50780]
% Bucle for (en MATLAB es preferible vectorizar cuando sea posible)
suma = 0;
for i = 1:5
    suma = suma + i;
end

% Bucle while
cont = 0;
while cont < 3
    cont = cont + 1;
end
%%
%%\ 10. Proyecto Final: Análisis de un "espectro" simulado
% Creamos el espectro simulado
longitud_onda   = 400:1:700; % rango de la longitud de onda
mu = 550;                    % lambda_average
sigma = 20;                  % lambda_desv_est

signal = (1 / (sqrt(2*pi) * sigma)) * exp(-((longitud_onda - mu)/(sqrt(2)*sigma)).^2);
fondo  = randn(1, length(longitud_onda)); % distribucion gaussiana: mu = 0, desv est = 1
intensidad = fondo * 0.002 + signal ;

% Buscar el pico de intensidad
[max_int, idx_pico] = max(intensidad);
lambda_pico = longitud_onda(idx_pico);

figure; %[output:3c8957e8]
plot(longitud_onda, intensidad, 'cyan'); %[output:3c8957e8]
hold on; %[output:3c8957e8]
plot(lambda_pico, max_int, 'ro', 'MarkerSize', 8, 'MarkerFaceColor', 'r'); %[output:3c8957e8]
title(['Espectro - Pico en \lambda = ', num2str(lambda_pico), ' nm']); %[output:3c8957e8]
xlabel('Longitud de onda (nm)'); ylabel('Intensidad'); %[output:3c8957e8]

